__NUXT_JSONP__("/por/how-to-apply-for-a-student-visa", {data:[{details:{slug:"por",pageTitle:"Como solicitar um visto de estudante | Mentor Language Institute",pageDescription:"Existem várias etapas para solicitar um visto de estudante (visto F1). ",title:"Como solicitar um visto de estudante",subtitle:["Existem várias etapas para solicitar um visto de estudante (visto F1). A ordem dessas etapas e como você as conclui podem variar de acordo com a Embaixada ou Consulado dos Estados Unidos em cada país. Consulte as instruções \u003Ca title=\"Find a U.S. Embassy or Consulate\" href=\"http:\u002F\u002Fwww.usembassy.gov\u002F\" target=\"_blank\"\u003Eno site da embaixada ou consulado\u003C\u002Fa\u003E",null,"O vídeo de instruções sobre o visto de estudante abaixo fornecerá um procedimento geral para solicitar e obter um visto de estudante."],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002FpcTnih691z4?feature=oembed",other_description:["Você pode baixar o material de apresentação no link abaixo.","\u003Cstrong\u003EBaixe o vídeo\u003C\u002Fstrong\u003E \u003Ca href=\"\u002Fdocuments\u002FHow_to_Apply_for_a_student_visa-por.pdf\" target=\"_blank\"\u003E\u003Cstrong\u003EComo Solicitar um visto de Estudante\u003C\u002Fstrong\u003E\u003C\u002Fa\u003E"],dir:"\u002Fhow-to-apply-for-a-student-visa",path:"\u002Fhow-to-apply-for-a-student-visa\u002Fpor",extension:".json",createdAt:"2026-10-22T16:31:29.675Z",updatedAt:"2025-05-26T12:06:27.788Z"}}],fetch:{},mutations:void 0});